class Node:

	def __init__(self, data):
		self.data = data
		self.next = None

class Solution:

	def sortList(self, head):
		a = head
		while a.next:
			if a.next.data < 0:
				k = a.next
				if a.next.next:
					a.next = a.next.next
				else:
					a.next = None
				k.next = head
				head = k
			else:
				a = a.next
		return head
